const args = $input.first().json;
const raw = String(args.query || '').trim();
const sessionId = String(args.session_id || 'unknown');

if (!raw) {
  return [{ json: { _skip: true, status: 'NOT_FOUND', message_to_agent: 'Faltó la consulta. Pedile al cliente más detalle.', trace_id: $execution.id } }];
}

const q = raw.toLowerCase();

// Detectar intent
let intent = 'equipo';
if (/usad|refurbish|reaco|bizhub|accurio|konica\s*minolt/i.test(q)) {
  intent = 'inventario';
} else if (/imprim|estamp|gorra|remera|bandera|wrap|cartel|vinil|sticker|adhesi|stand|prend|tela|algodon|polyester|aplicacion|sublimacion/i.test(q) && !/huenu|dlican|teneth|hanrun|xenons|sinajet|riso/i.test(q)) {
  intent = 'aplicacion';
}

// Extraer hints
const brands = ['huenu','dlican','teneth','hanrun','xenons','riso','sinajet'];
const brand = brands.find(b => q.includes(b)) || '';
const marca = brand ? brand.toUpperCase() : '';

const techMap = {
  'dtf textil': 'DTF Textil',
  'dtf uv': 'DTF UV',
  'sublim': 'Sublimación',
  'eco-solvente': 'Eco-Solvente',
  'eco solvente': 'Eco-Solvente',
  'solvente': 'Solvente',
  'gran formato': 'Gran Formato',
  'idl': 'IDL Láser',
  'laser': 'IDL Láser',
  'corte': 'Corte',
  'plotter': 'Corte',
};
let tecnologia = '';
for (const [k, v] of Object.entries(techMap)) {
  if (q.includes(k)) { tecnologia = v; break; }
}
if (!tecnologia && /\buv\b/i.test(q)) tecnologia = 'UV';
if (!tecnologia && /\bdtf\b/i.test(q)) tecnologia = 'DTF Textil';

return [{
  json: {
    intent,
    query_raw: raw,
    query_lower: q,
    session_id: sessionId,
    marca,
    tecnologia,
    trace_id: $execution.id
  }
}];

const ctx = $('Classify Intent').first().json;
const rows = $input.all().map(i => i.json).filter(r => r && (r.id || r.fields));

if (rows.length === 0) {
  return [{ json: {
    status: 'NOT_FOUND',
    data: null,
    message_to_agent: `No encontré coincidencias en el catálogo para "${ctx.query_raw}" (intent: ${ctx.intent}). Decile al cliente que verifiquen el equipo correcto al comercial.`,
    trace_id: ctx.trace_id,
    intent: ctx.intent
  } }];
}

const items = rows.slice(0, 5).map(r => {
  const f = r.fields || r;
  return {
    modelo: f['Modelo'] || f['Nombre'] || '',
    marca: f['Marca'] || '',
    tecnologia: f['Tecnología'] || f['Tecnologia'] || [],
    ancho: f['Ancho'] || '',
    descripcion: f['Descripción corta'] || f['Descripcion corta'] || f['Descripción'] || '',
    aplicaciones: f['Aplicaciones compatibles'] || [],
    sustratos: f['Sustratos tipicos'] || f['Sustratos típicos'] || [],
    disponibilidad: f['Disponibilidad zona'] || [],
    contador_copias: f['Contador de copias'] || null,
  };
}).filter(it => it.modelo);

return [{ json: {
  status: items.length ? 'RESOLVED' : 'NOT_FOUND',
  data: { intent: ctx.intent, total: items.length, items },
  message_to_agent: items.length
    ? `Encontré ${items.length} match(es) en el catálogo (intent: ${ctx.intent}). Integrá los datos en tu respuesta sin inventar specs.`
    : `No encontré matches concretos para "${ctx.query_raw}". Pedile al cliente más detalle o derivá al comercial.`,
  trace_id: ctx.trace_id
} }];
